#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Deployment values are personal and Mise is open source (ADR 0005): keep them outside the repo.
ENV_FILE="${MISE_DEPLOY_ENV:-${XDG_CONFIG_HOME:-$HOME/.config}/mise/deploy.env}"
mkdir -p "$(dirname "$ENV_FILE")"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# gh picks the repository from the working directory.
cd "$REPO_ROOT"

# yaml_str VALUE prints VALUE as a double-quoted YAML string.
yaml_str() { local v="${1//\\/\\\\}"; printf '"%s"' "${v//\"/\\\"}"; }

banner "Deploy Mise to your own hostname"
note "Values you enter are saved to $ENV_FILE, never to the repo."

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pulumi Cloud: login and access token"
say "Pulumi Cloud keeps the infrastructure state; CI signs in with an access token."
for tool in pulumi gh bun; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed: install it and re-run"; exit 1; }
done
gh auth status >/dev/null 2>&1 || warn "gh is not signed in: run 'gh auth login' now, in another terminal"
if ! pulumi whoami >/dev/null 2>&1; then
  step "Signing you in to Pulumi Cloud (a browser window opens)."
  pulumi login
fi
note "Signed in to Pulumi as $(pulumi whoami)."
ask PULUMI_ORG "Pulumi organization to deploy under (your username for a personal account):"
write_env PULUMI_ORG "$PULUMI_ORG"
open_url "https://app.pulumi.com/account/tokens"
step "Create token → Personal access token → name it 'mise-ci' → Create → copy it."
ask_secret PULUMI_ACCESS_TOKEN "Paste the Pulumi access token:"
write_env PULUMI_ACCESS_TOKEN "$PULUMI_ACCESS_TOKEN"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: account, zone, hostname and Zero Trust team"
open_url "https://dash.cloudflare.com/"
step "Pick your account. Account home → the ⋯ menu on the account → Copy account ID."
ask CF_ACCOUNT_ID "Cloudflare account ID:"
step "Your zone is the domain listed under Domains (e.g. example.com)."
ask CF_ZONE "Zone:"
ask MISE_HOSTNAME "Hostname to serve Mise at (e.g. mise.example.com):"
open_url "https://one.dash.cloudflare.com/"
step "First time: finish onboarding (choose a team name and the Free plan), or the API refuses Access changes."
step "Zero Trust → Settings → Team name and domain."
ask ACCESS_TEAM_DOMAIN "Team domain (e.g. example.cloudflareaccess.com):"
ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN#https://}"; ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN%/}"
write_env CF_ACCOUNT_ID "$CF_ACCOUNT_ID"
write_env CF_ZONE "$CF_ZONE"
write_env MISE_HOSTNAME "$MISE_HOSTNAME"
write_env ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "R2 holds photos and nightly exports. If it isn't enabled yet: Enable R2 (the free tier asks for a payment method)."
pause "Press Enter once R2 shows its overview page"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: API token for Pulumi and Wrangler"
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token → name it 'mise-ci'. Add these permissions:"
note "  Account · Workers Scripts · Edit"
note "  Account · Workers R2 Storage · Edit"
note "  Account · Access: Apps and Policies · Edit"
note "  Account · Access: Organizations, Identity Providers, and Groups · Edit"
note "  Zone · Workers Routes · Edit"
note "  Zone · DNS · Edit"
step "Account Resources: your account. Zone Resources: Specific zone → $CF_ZONE."
step "Continue to summary → Create Token → copy it."
ask_secret CLOUDFLARE_API_TOKEN "Paste the Cloudflare API token:"
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google: OAuth client for 'Sign in with Google'"
say "Access needs a Google OAuth client to offer Google sign-in."
open_url "https://console.cloud.google.com/auth/clients"
step "Pick or create a project. If asked, configure the consent screen: External (or Internal for a Workspace)."
step "Create client → Application type: Web application → name it 'Mise Access'."
step "Authorized JavaScript origins: https://$ACCESS_TEAM_DOMAIN"
step "Authorized redirect URIs: https://$ACCESS_TEAM_DOMAIN/cdn-cgi/access/callback"
step "Create → copy the Client ID and Client secret."
ask GOOGLE_CLIENT_ID "Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Client secret:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
note "An External app in 'Testing' only lets in the test users you list on its Audience page."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Who may sign in"
say "List the Google accounts allowed in, or a Google Workspace domain, or both."
ask ALLOWED_EMAILS "Allowed emails, comma-separated (blank for none):" || true
ask ALLOWED_EMAIL_DOMAIN "Allowed Workspace domain (blank for none):" || true
if [[ -z "${ALLOWED_EMAILS:-}" && -z "${ALLOWED_EMAIL_DOMAIN:-}" ]]; then
  warn "With neither, no one could sign in. Re-run and enter at least one."; exit 1
fi
write_env ALLOWED_EMAILS "${ALLOWED_EMAILS:-}"
write_env ALLOWED_EMAIL_DOMAIN "${ALLOWED_EMAIL_DOMAIN:-}"
say "An Anthropic API key for the chat's agent (console.anthropic.com → API keys)."
say "Set a monthly spend limit there too (Settings → Limits): Mise has no cap of its own."
ask_secret ANTHROPIC_API_KEY "Anthropic API key (blank to skip; the chat then answers nothing):" || true
write_env ANTHROPIC_API_KEY "${ANTHROPIC_API_KEY:-}"
say "Optional: an OpenAI API key for voice (platform.openai.com → API keys)."
say "Set a monthly budget there too (Settings → Limits)."
ask_secret OPENAI_API_KEY "OpenAI API key (blank to skip; there is then no voice):" || true
write_env OPENAI_API_KEY "${OPENAI_API_KEY:-}"
say "Optional: a Google Drive folder whose Docs become Drafts (README → Google Drive folder has the steps)."
ask DRIVE_KEY_FILE "Path to the service account's JSON key file (blank to skip):" || true
DRIVE_KEY_FILE="${DRIVE_KEY_FILE/#\~/$HOME}"
if [[ -n "${DRIVE_KEY_FILE:-}" ]]; then
  [[ -r "$DRIVE_KEY_FILE" ]] || { warn "Can't read $DRIVE_KEY_FILE. Re-run with the key file's path."; exit 1; }
  ask DRIVE_FOLDER_ID "Drive folder id (the end of the folder's URL):"
fi
write_env DRIVE_KEY_FILE "${DRIVE_KEY_FILE:-}"
write_env DRIVE_FOLDER_ID "${DRIVE_FOLDER_ID:-}"
say "Notifications need a VAPID key, which Mise makes and keeps (README → Notifications)."
VAPID_PRIVATE_KEY="$(_existing VAPID_PRIVATE_KEY || true)"
if [[ -n "$VAPID_PRIVATE_KEY" ]]; then
  note "Keeping the VAPID key from an earlier run: a new one would turn notifications off on every device."
else
  # A P-256 private key, PKCS#8 DER, base64 on one line.
  VAPID_PRIVATE_KEY=$(openssl ecparam -name prime256v1 -genkey -noout | openssl pkcs8 -topk8 -nocrypt -outform DER | base64 | tr -d '\n')
  note "Made a new VAPID key."
fi
write_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
say "Optional: a Sentry DSN for error reports (sentry.io → Project → Settings → Client Keys)."
ask_secret SENTRY_DSN "Sentry DSN (blank to skip):" || true
write_env SENTRY_DSN "${SENTRY_DSN:-}"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Pulumi ESC environment and stack"
ESC_ENV="mise/production"
STACK="$PULUMI_ORG/mise/production"
say "Writing your settings to the ESC environment $PULUMI_ORG/$ESC_ENV and creating the stack $STACK."
definition=$(mktemp); trap 'rm -f "$definition"' EXIT
{
  printf 'values:\n  pulumiConfig:\n'
  printf '    mise:accountId: %s\n' "$(yaml_str "$CF_ACCOUNT_ID")"
  printf '    mise:zone: %s\n' "$(yaml_str "$CF_ZONE")"
  printf '    mise:hostname: %s\n' "$(yaml_str "$MISE_HOSTNAME")"
  printf '    mise:accessTeamDomain: %s\n' "$(yaml_str "$ACCESS_TEAM_DOMAIN")"
  if [[ -n "${ALLOWED_EMAILS:-}" ]]; then
    printf '    mise:allowedEmails:\n'
    IFS=',' read -ra emails <<< "$ALLOWED_EMAILS"
    for email in "${emails[@]}"; do printf '      - %s\n' "$(yaml_str "$(echo "$email" | xargs)")"; done
  fi
  [[ -n "${ALLOWED_EMAIL_DOMAIN:-}" ]] && printf '    mise:allowedEmailDomain: %s\n' "$(yaml_str "$ALLOWED_EMAIL_DOMAIN")"
  printf '    mise:googleClientId: %s\n' "$(yaml_str "$GOOGLE_CLIENT_ID")"
  printf '    mise:googleClientSecret:\n      fn::secret: %s\n' "$(yaml_str "$GOOGLE_CLIENT_SECRET")"
  [[ -n "${ANTHROPIC_API_KEY:-}" ]] && printf '    mise:anthropicApiKey:\n      fn::secret: %s\n' "$(yaml_str "$ANTHROPIC_API_KEY")"
  [[ -n "${OPENAI_API_KEY:-}" ]] && printf '    mise:openaiApiKey:\n      fn::secret: %s\n' "$(yaml_str "$OPENAI_API_KEY")"
  if [[ -n "${DRIVE_KEY_FILE:-}" && -n "${DRIVE_FOLDER_ID:-}" ]]; then
    printf '    mise:driveFolderId: %s\n' "$(yaml_str "$DRIVE_FOLDER_ID")"
    # The key's JSON on one line: its private key's line breaks are escaped inside the JSON.
    printf '    mise:googleServiceAccountKey:\n      fn::secret: %s\n' "$(yaml_str "$(tr -d '\n' < "$DRIVE_KEY_FILE")")"
  fi
  printf '    mise:vapidPrivateKey:\n      fn::secret: %s\n' "$(yaml_str "$VAPID_PRIVATE_KEY")"
  [[ -n "${SENTRY_DSN:-}" ]] && printf '    mise:sentryDsn:\n      fn::secret: %s\n' "$(yaml_str "$SENTRY_DSN")"
  true
} > "$definition"
if pulumi env get "$PULUMI_ORG/$ESC_ENV" >/dev/null 2>&1; then
  confirm "The environment exists already. Replace its definition with these values?" &&
    pulumi env edit "$PULUMI_ORG/$ESC_ENV" --file "$definition"
else
  pulumi env init "$PULUMI_ORG/$ESC_ENV" --file "$definition"
fi
rm -f "$definition"
(
  cd "$REPO_ROOT/infra"
  pulumi stack select "$STACK" 2>/dev/null || pulumi stack init "$STACK"
  if ! pulumi config env ls 2>/dev/null | grep -qF "$ESC_ENV"; then
    pulumi config env add "$ESC_ENV" --yes >/dev/null
  fi
)
note "infra/Pulumi.production.yaml now imports $ESC_ENV; it is gitignored."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitHub: secrets and variables for CI"
say "The deploy job reads two secrets and two variables."
set_secret PULUMI_ACCESS_TOKEN "$PULUMI_ACCESS_TOKEN"
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_var PULUMI_STACK "$STACK"
set_var PULUMI_ESC_ENVIRONMENT "$ESC_ENV"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy and check sign-in"
say "The deploy job runs on every push to master, or by hand."
started=0
git fetch --quiet origin master 2>/dev/null || true
if [[ -n "$(git rev-list origin/master..master 2>/dev/null)" ]]; then
  warn "Your master has commits GitHub doesn't have yet, and CI deploys what is on GitHub."
  confirm "Push master now? That starts the deploy." && git push origin master && started=1
elif confirm "Run the CI workflow on master now?"; then
  if gh workflow run ci.yml --ref master; then started=1
  else warn "Couldn't start the workflow: push to master to deploy, then re-run this wizard."; fi
fi
if (( started )); then
  note "Pick the run that just started (it can take a few seconds to appear)."
  sleep 5
  if ! gh run watch --exit-status; then
    warn "The deploy failed: read the failed step with 'gh run view --log-failed', fix it, and re-run this wizard."
    exit 1
  fi
fi
open_url "https://$MISE_HOSTNAME"
step "Sign in with an allowed Google account: the Mise setup screen appears."
step "In a private window, sign in with an account that is not allowed: Access refuses it."
step "Visit https://$MISE_HOSTNAME/cal/test.ics: no sign-in page (Not found until the calendar ships)."
pause "Press Enter once all three check out"

finish
}

run_wizard "$@"; exit
